<script lang="ts">
    import { open, save } from '@tauri-apps/plugin-dialog';
  import { onMount } from 'svelte';
  import { run } from './lib/api';
  import { classes, types, type Student, type Income, type Expense, type Summary } from './lib/types';
  let page='dashboard', students:Student[]=[], incomes:Income[]=[], expenses:Expense[]=[], summary:Summary={total_income:0,total_expense:0,balance:0,recent:[],expenses:[]};
  let query='', classFilter='', from='', to='', message='', error='', busy=false, saving=false, modal='';
  let studentForm={id:0,name:'',class_name:classes[0]}, incomeForm={student_id:0,date:new Date().toISOString().slice(0,10),amount:'',payment_type:types[0],note:''}, expenseForm={id:0,date:new Date().toISOString().slice(0,10),amount:'',note:''};
  let report={income:0,expense:0,balance:0,by_class:[] as {class_name:string,amount:number}[],by_type:[] as {payment_type:string,amount:number}[],incomes:[] as Income[],expenses:[] as Expense[]};
  const money=(n:number)=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);
  async function load(){busy=true;try{[students,incomes,expenses,summary]=await Promise.all([run<Student[]>('list_students'),run<Income[]>('list_incomes'),run<Expense[]>('list_expenses'),run<Summary>('dashboard')]); await loadReport();}catch(e){error=String(e)}finally{busy=false}}
  async function loadReport(){try{report=await run('report',{fromDate:from||null,toDate:to||null})}catch(e){error=String(e)}}
  onMount(load);
  function notify(s:string){message=s;error='';setTimeout(()=>message='',3500)}
  async function saveStudent(){if(saving)return;saving=true;try{await run(studentForm.id?'update_student':'add_student',{student:studentForm});modal='';notify('Data siswa berhasil disimpan.');await load()}catch(e){error=String(e)}finally{saving=false}}
  async function deactivate(s:Student){if(confirm(`Nonaktifkan ${s.name}? Riwayat transaksi tetap tersimpan.`)){try{await run('deactivate_student',{id:s.id});notify('Siswa dinonaktifkan.');await load()}catch(e){error=String(e)}}}
  async function saveIncome(){if(saving)return;saving=true;try{await run('add_income',{input:{...incomeForm,amount:Number(incomeForm.amount)}});modal='';incomeForm={student_id:0,date:new Date().toISOString().slice(0,10),amount:'',payment_type:types[0],note:''};notify('Pemasukan berhasil dicatat.');await load()}catch(e){error=String(e)}finally{saving=false}}
  async function saveExpense(){if(saving)return;saving=true;try{await run(expenseForm.id?'update_expense':'add_expense',{input:{...expenseForm,amount:Number(expenseForm.amount)}});modal='';expenseForm={id:0,date:new Date().toISOString().slice(0,10),amount:'',note:''};notify('Pengeluaran berhasil disimpan.');await load()}catch(e){error=String(e)}finally{saving=false}}
  $: filteredStudents=students.filter(s=>(!query||s.name.toLowerCase().includes(query.toLowerCase()))&&(!classFilter||s.class_name===classFilter));
  $: filteredIncomes=incomes.filter(i=>(!query||`${i.student_name} ${i.payment_type}`.toLowerCase().includes(query.toLowerCase()))&&(!classFilter||i.class_name===classFilter)&&(!from||i.date>=from)&&(!to||i.date<=to));
  $: filteredExpenses=expenses.filter(i=>(!from||i.date>=from)&&(!to||i.date<=to));
  $: eligibleStudents=students.filter(s=>s.active&&(!classFilter||s.class_name===classFilter));
  async function chooseImport(){try{const path=await open({multiple:false,filters:[{name:'Excel',extensions:['xlsx']}]});if(!path)return;const preview=await run<{sheets:string[],headers:string[],rows:{name:string,class_name:string,valid:boolean,reason:string}[]}>('preview_student_import',{path});importData={path,...preview,sheet:preview.sheets[0]||'',nameCol:preview.headers.findIndex(h=>h.toLowerCase().includes('nama')),classCol:preview.headers.findIndex(h=>h.toLowerCase().includes('kelas'))};if(importData.nameCol<0)importData.nameCol=0;if(importData.classCol<0)importData.classCol=Math.min(1,Math.max(importData.headers.length-1,0));modal='import'}catch(e){error=String(e)}}
  let importData:{path:string,sheets:string[],headers:string[],rows:{name:string,class_name:string,valid:boolean,reason:string}[],sheet:string,nameCol:number,classCol:number}={path:'',sheets:[],headers:[],rows:[],sheet:'',nameCol:0,classCol:1};
  async function refreshImport(){try{const preview=await run<{sheets:string[],headers:string[],rows:{name:string,class_name:string,valid:boolean,reason:string}[]}>('preview_student_import',{path:importData.path,sheet:importData.sheet,nameColumn:importData.nameCol,classColumn:importData.classCol});importData={...importData,...preview}}catch(e){error=String(e)}}
  async function confirmImport(){if(saving)return;saving=true;try{const result=await run<{success:number,failed:number}>('import_students',{path:importData.path,sheet:importData.sheet,nameColumn:importData.nameCol,classColumn:importData.classCol});modal='';notify(`Impor selesai: ${result.success} berhasil, ${result.failed} dilewati.`);await load()}catch(e){error=String(e)}finally{saving=false}}
  async function exportFile(kind:'csv'|'pdf'){try{const path=await save({defaultPath:`laporan-bendahara.${kind}`,filters:[{name:kind.toUpperCase(),extensions:[kind]}]});if(!path)return;await run(kind==='csv'?'export_csv':'export_pdf',{path,fromDate:from||null,toDate:to||null});notify(`Laporan ${kind.toUpperCase()} berhasil disimpan.`)}catch(e){error=String(e)}}
  async function backup(){try{const path=await save({defaultPath:'backup-bendahara.sqlite',filters:[{name:'SQLite',extensions:['sqlite']}]});if(path){await run('backup_database',{path});notify('Backup database berhasil dibuat.')}}catch(e){error=String(e)}}
</script>

<svelte:head><title>Bendahara Sekolah</title></svelte:head>
<div class="app-shell">
  <aside class="sidebar"><div class="brand"><div class="brand-mark">BS</div><div><strong>Bendahara</strong><small>Administrasi sekolah</small></div></div>
    <div class="nav-label">MENU UTAMA</div><nav>{#each [['dashboard','Ringkasan','⌂'],['students','Data siswa','♙'],['income','Pemasukan','＋'],['expense','Pengeluaran','−'],['report','Rekap & laporan','▤']] as item}<button class:active={page===item[0]} onclick={()=>{page=item[0];query=''}}><span>{item[2]}</span>{item[1]}</button>{/each}</nav>
    <div class="sidebar-bottom"><div class="offline"><i></i><span>Data tersimpan di perangkat ini</span></div><button class="backup" onclick={backup}>Simpan cadangan database</button><small class="version">Aplikasi Bendahara Sekolah</small></div>
  </aside>
  <main><header><div><div class="eyebrow">ADMINISTRASI KEUANGAN</div><h1>{({dashboard:'Ringkasan',students:'Data siswa',income:'Pemasukan',expense:'Pengeluaran',report:'Rekap & laporan'} as Record<string,string>)[page]}</h1></div><div class="header-right"><span class="today">{new Intl.DateTimeFormat('id-ID',{dateStyle:'full'}).format(new Date())}</span><div class="avatar">B</div></div></header>
    {#if message}<div class="toast success">✓ {message}</div>{/if}{#if error}<div class="toast danger">{error}<button onclick={()=>error=''}>Tutup</button></div>{/if}
    {#if page==='dashboard'}
      <section class="welcome"><div><span class="pill">● RINGKASAN KEUANGAN</span><h2>Selamat datang di pembukuan sekolah</h2><p>Pantau pemasukan dan pengeluaran dengan mudah.</p></div><button class="button primary" onclick={()=>{incomeForm.student_id=0;modal='income'}}>＋ Catat pemasukan</button></section>
      <section class="cards"><article class="stat"><span>Total pemasukan</span><strong>{money(summary.total_income)}</strong><small>Seluruh transaksi tersimpan</small><div class="stat-icon green">↗</div></article><article class="stat"><span>Total pengeluaran</span><strong>{money(summary.total_expense)}</strong><small>Seluruh transaksi tersimpan</small><div class="stat-icon orange">↘</div></article><article class="stat balance"><span>Saldo saat ini</span><strong>{money(summary.balance)}</strong><small>Pemasukan dikurangi pengeluaran</small><div class="stat-icon blue">◈</div></article></section>
      <section class="panel"><div class="panel-heading"><div><h3>Transaksi terbaru</h3><p>Pemasukan dan pengeluaran terkini</p></div><button class="text-button" onclick={()=>page='report'}>Lihat laporan →</button></div>{#if summary.recent.length===0&&summary.expenses.length===0}<div class="empty"><div>▤</div><strong>Belum ada transaksi</strong><p>Transaksi yang Anda catat akan tampil di sini.</p><button class="button primary" onclick={()=>modal='income'}>Catat pemasukan pertama</button></div>{:else}<div class="table-wrap"><table><thead><tr><th>TANGGAL</th><th>TRANSAKSI</th><th>KATEGORI</th><th>JENIS</th><th class="right">NOMINAL</th></tr></thead><tbody>{#each [...summary.recent.map(i=>({...i,kind:'Pemasukan'})),...summary.expenses.slice(0,5).map(e=>({...e,student_name:e.note,class_name:'—',payment_type:'Pengeluaran',kind:'Pengeluaran'}))].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8) as t}<tr><td>{t.date}</td><td><strong>{t.student_name||t.note}</strong><small class="subrow">{t.class_name}</small></td><td>{t.payment_type}</td><td><span class:income-tag={t.kind==='Pemasukan'} class:expense-tag={t.kind==='Pengeluaran'} class="tag">{t.kind}</span></td><td class="right" class:positive={t.kind==='Pemasukan'} class:negative={t.kind==='Pengeluaran'}>{t.kind==='Pemasukan'?'+':'−'} {money(t.amount)}</td></tr>{/each}</tbody></table></div>{/if}</section>
    {:else if page==='students'}
      <section class="page-intro"><div><p>Kelola daftar siswa dan kelas.</p></div><div class="button-row"><button class="button secondary" onclick={chooseImport}>⇧ Impor Excel</button><button class="button primary" onclick={()=>{studentForm={id:0,name:'',class_name:classes[0]};modal='student'}}>＋ Tambah siswa</button></div></section>
      <section class="panel"><div class="toolbar"><input class="search" placeholder="⌕  Cari nama siswa..." bind:value={query}/><select bind:value={classFilter}><option value="">Semua kelas</option>{#each classes as c}<option>{c}</option>{/each}</select><span class="count">{filteredStudents.length} siswa</span></div><div class="table-wrap"><table><thead><tr><th>NAMA SISWA</th><th>KELAS</th><th>STATUS</th><th></th></tr></thead><tbody>{#each filteredStudents as s}<tr><td><strong>{s.name}</strong></td><td>{s.class_name}</td><td><span class:status-on={s.active} class:status-off={!s.active} class="tag">{s.active?'Aktif':'Nonaktif'}</span></td><td class="right actions"><button onclick={()=>{studentForm={id:s.id,name:s.name,class_name:s.class_name};modal='student'}}>Ubah</button>{#if s.active}<button class="danger-link" onclick={()=>deactivate(s)}>Nonaktifkan</button>{/if}</td></tr>{/each}</tbody></table>{#if filteredStudents.length===0}<div class="empty compact"><strong>Data siswa belum tersedia</strong><p>Tambahkan siswa atau impor dari Excel.</p></div>{/if}</div></section>
    {:else if page==='income'}
      <section class="page-intro"><p>Catat pembayaran siswa dan telusuri riwayat pemasukan.</p><button class="button primary" onclick={()=>{incomeForm={student_id:0,date:new Date().toISOString().slice(0,10),amount:'',payment_type:types[0],note:''};modal='income'}}>＋ Catat pemasukan</button></section>
      <section class="panel"><div class="toolbar"><input class="search" placeholder="⌕  Cari siswa atau pembayaran..." bind:value={query}/><select bind:value={classFilter}><option value="">Semua kelas</option>{#each classes as c}<option>{c}</option>{/each}</select><input type="date" bind:value={from} aria-label="Dari tanggal"/><input type="date" bind:value={to} aria-label="Sampai tanggal"/><span class="count">{filteredIncomes.length} transaksi</span></div><div class="table-wrap"><table><thead><tr><th>TANGGAL</th><th>SISWA</th><th>KELAS</th><th>PEMBAYARAN</th><th class="right">NOMINAL</th></tr></thead><tbody>{#each filteredIncomes as i}<tr><td>{i.date}</td><td><strong>{i.student_name}</strong></td><td>{i.class_name}</td><td>{i.payment_type}</td><td class="right positive">+ {money(i.amount)}</td></tr>{/each}</tbody></table></div></section>
    {:else if page==='expense'}
      <section class="page-intro"><p>Catat dan tinjau penggunaan dana sekolah.</p><button class="button primary" onclick={()=>{expenseForm={id:0,date:new Date().toISOString().slice(0,10),amount:'',note:''};modal='expense'}}>＋ Catat pengeluaran</button></section>
      <section class="panel"><div class="toolbar"><span class="count">{filteredExpenses.length} transaksi</span><input type="date" bind:value={from} aria-label="Dari tanggal"/><input type="date" bind:value={to} aria-label="Sampai tanggal"/></div><div class="table-wrap"><table><thead><tr><th>TANGGAL</th><th>KETERANGAN</th><th class="right">NOMINAL</th><th></th></tr></thead><tbody>{#each filteredExpenses as e}<tr><td>{e.date}</td><td><strong>{e.note}</strong></td><td class="right negative">− {money(e.amount)}</td><td class="right actions"><button onclick={()=>{expenseForm={id:e.id,date:e.date,amount:String(e.amount),note:e.note};modal='expense'}}>Ubah</button></td></tr>{/each}</tbody></table></div></section>
    {:else}
      <section class="page-intro report-intro"><p>Pilih periode untuk melihat rekap transaksi.</p><div class="button-row"><button class="button secondary" onclick={()=>exportFile('csv')}>↓ Ekspor CSV</button><button class="button secondary" onclick={()=>exportFile('pdf')}>↓ Ekspor PDF</button></div></section>
      <section class="panel period"><label>Dari tanggal<input type="date" bind:value={from} onchange={loadReport}/></label><label>Sampai tanggal<input type="date" bind:value={to} onchange={loadReport}/></label><button class="button secondary" onclick={loadReport}>Tampilkan rekap</button></section>
      <section class="cards report-cards"><article class="stat"><span>Total pemasukan</span><strong>{money(report.income)}</strong></article><article class="stat"><span>Total pengeluaran</span><strong>{money(report.expense)}</strong></article><article class="stat balance"><span>Saldo periode</span><strong>{money(report.balance)}</strong></article></section>
      <div class="report-grid"><section class="panel"><div class="panel-heading"><div><h3>Pemasukan per kelas</h3><p>Berdasarkan snapshot kelas transaksi</p></div></div><div class="simple-list">{#each report.by_class as row}<div><span>{row.class_name}</span><strong>{money(row.amount)}</strong></div>{/each}{#if !report.by_class.length}<div class="muted">Tidak ada pemasukan dalam periode ini.</div>{/if}</div></section><section class="panel"><div class="panel-heading"><div><h3>Pemasukan per jenis</h3><p>Rincian kategori pembayaran</p></div></div><div class="simple-list">{#each report.by_type as row}<div><span>{row.payment_type}</span><strong>{money(row.amount)}</strong></div>{/each}{#if !report.by_type.length}<div class="muted">Tidak ada pemasukan dalam periode ini.</div>{/if}</div></section></div>
    {/if}
    <footer>Semua nominal dalam Rupiah · Data disimpan secara lokal di perangkat Anda</footer>
  </main>
</div>

{#if modal}<div class="overlay" role="presentation" onclick={(e)=>{if(e.target===e.currentTarget)modal=''}}><section class="dialog" role="dialog" aria-modal="true"><button class="close" aria-label="Tutup" onclick={()=>modal=''}>×</button>
  {#if modal==='student'}<h2>{studentForm.id?'Ubah data siswa':'Tambah siswa'}</h2><p class="dialog-sub">Isi nama dan kelas siswa.</p><form onsubmit={(e)=>{e.preventDefault();saveStudent()}}><label>Nama siswa<input required maxlength="120" bind:value={studentForm.name} placeholder="Nama lengkap siswa"/></label><label>Kelas<select bind:value={studentForm.class_name}>{#each classes as c}<option>{c}</option>{/each}</select></label><div class="dialog-actions"><button type="button" class="button secondary" onclick={()=>modal=''}>Batal</button><button class="button primary">Simpan data</button></div></form>
  {:else if modal==='income'}<h2>Catat pemasukan</h2><p class="dialog-sub">Pilih siswa dan isi detail pembayaran.</p><form onsubmit={(e)=>{e.preventDefault();saveIncome()}}><label>Kelas<select bind:value={classFilter} onchange={()=>incomeForm.student_id=0}><option value="">Pilih kelas</option>{#each classes as c}<option>{c}</option>{/each}</select></label><label>Nama siswa<select required bind:value={incomeForm.student_id}><option value={0} disabled>Pilih siswa</option>{#each eligibleStudents as s}<option value={s.id}>{s.name}</option>{/each}</select></label><div class="form-row"><label>Tanggal<input type="date" required bind:value={incomeForm.date}/></label><label>Jenis pembayaran<select bind:value={incomeForm.payment_type}>{#each types as t}<option>{t}</option>{/each}</select></label></div><label>Nominal (Rp)<input type="number" min="1" step="1" required bind:value={incomeForm.amount} placeholder="Contoh: 150000"/></label><label>Keterangan tambahan <span class="optional">(opsional)</span><input maxlength="200" bind:value={incomeForm.note}/></label><div class="dialog-actions"><button type="button" class="button secondary" onclick={()=>modal=''}>Batal</button><button class="button primary">Simpan pemasukan</button></div></form>
  {:else if modal==='expense'}<h2>{expenseForm.id?'Ubah pengeluaran':'Catat pengeluaran'}</h2><p class="dialog-sub">Isi tanggal, nominal, dan keterangan.</p><form onsubmit={(e)=>{e.preventDefault();saveExpense()}}><label>Tanggal<input type="date" required bind:value={expenseForm.date}/></label><label>Nominal (Rp)<input type="number" min="1" step="1" required bind:value={expenseForm.amount} placeholder="Contoh: 50000"/></label><label>Keterangan<input required maxlength="250" bind:value={expenseForm.note} placeholder="Contoh: Pembelian alat tulis"/></label><div class="dialog-actions"><button type="button" class="button secondary" onclick={()=>modal=''}>Batal</button><button class="button primary">Simpan pengeluaran</button></div></form>
  {:else}<h2>Pratinjau impor siswa</h2><p class="dialog-sub">Pastikan sheet dan kolom sudah sesuai sebelum menyimpan.</p><div class="form-row"><label>Sheet<select bind:value={importData.sheet} onchange={refreshImport}>{#each importData.sheets as s}<option>{s}</option>{/each}</select></label><label>Kolom nama<select bind:value={importData.nameCol} onchange={refreshImport}>{#each importData.headers as h,i}<option value={i}>{h||`Kolom ${i+1}`}</option>{/each}</select></label><label>Kolom kelas<select bind:value={importData.classCol} onchange={refreshImport}>{#each importData.headers as h,i}<option value={i}>{h||`Kolom ${i+1}`}</option>{/each}</select></label></div><div class="preview-table"><table><thead><tr><th>NAMA</th><th>KELAS</th><th>VALIDASI</th></tr></thead><tbody>{#each importData.rows.slice(0,8) as row}<tr><td>{row.name}</td><td>{row.class_name}</td><td>{row.valid?'Siap':row.reason}</td></tr>{/each}</tbody></table></div><p class="muted">{importData.rows.length} baris pratinjau (maks. 1.000). Kelas harus cocok dengan daftar kelas. Baris duplikat akan dilewati.</p><div class="dialog-actions"><button class="button secondary" onclick={()=>modal=''}>Batal</button><button class="button primary" disabled={saving} onclick={confirmImport}>{saving?'Mengimpor…':'Impor data'}</button></div>{/if}
</section></div>{/if}
